from django_datatables_view.base_datatable_view import BaseDatatableView
from django.contrib.auth.mixins import LoginRequiredMixin
from .models import VendorContract

class VendorContractDataTableView(LoginRequiredMixin, BaseDatatableView):
    model = VendorContract

    def get_columns(self):
        cols = ['id', 'vendor_name', 'service_type']
        # Only internal risk officers may inspect internal risk scores and liability caps
        if self.request.user.has_perm('contracts.view_risk_metrics'):
            cols.extend(['internal_risk_score', 'total_liability_cap'])
        return cols

    def get_order_columns(self):
        return self.get_columns()

    def get_initial_queryset(self):
        return VendorContract.objects.filter(vendor__assigned_users=self.request.user)

    def filter_queryset(self, qs):
        search = self.request.GET.get('search[value]', None)
        if search:
            qs = qs.filter(vendor_name__icontains=search)
        return qs
